-- ============================================================================
-- ALL-IN-ONE SQL SETUP SCRIPT FOR ORACLE DB (TARGET DATA WAREHOUSE)
-- Run this script in Oracle SQL Developer / SQL*Plus / Toad / DBeaver
-- to initialize all target dimensional tables so that BDD ETL Automation passes 100%.
-- ============================================================================

-- ============================================================================
-- TARGET CLOUD ORACLE DATABASE SCHEMA (AUTONOMOUS / OCI / EXADATA)
-- Dialect: Oracle Cloud SQL (19c / 21c / 23ai / Autonomous Data Warehouse)
-- Description: Enterprise Banking Data Platform & Dimensional Star Schema
--              Includes SCD Type 2 Customer dimension, PII Masking fields,
--              Standardized Statuses, Sequences, Constraints, and Error Quarantine.
-- ============================================================================

-- Clean up existing objects if re-running
BEGIN
   EXECUTE IMMEDIATE 'DROP TABLE FACT_TRANSACTIONS CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/
BEGIN
   EXECUTE IMMEDIATE 'DROP TABLE FACT_LOAN_PORTFOLIO CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/
BEGIN
   EXECUTE IMMEDIATE 'DROP TABLE DAILY_BALANCE_SUMMARY CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/
BEGIN
   EXECUTE IMMEDIATE 'DROP TABLE DIM_ACCOUNT CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/
BEGIN
   EXECUTE IMMEDIATE 'DROP TABLE DIM_CUSTOMER CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/
BEGIN
   EXECUTE IMMEDIATE 'DROP TABLE DIM_BRANCH CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/
BEGIN
   EXECUTE IMMEDIATE 'DROP TABLE ETL_REJECTED_RECORDS CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/

-- ----------------------------------------------------------------------------
-- 1. DIM_BRANCH: Standardized Branch Dimension
-- ----------------------------------------------------------------------------
CREATE TABLE DIM_BRANCH (
    BRANCH_SK               NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    BRANCH_CODE             VARCHAR2(10) NOT NULL UNIQUE,
    BRANCH_NAME             VARCHAR2(100) NOT NULL,
    REGION                  VARCHAR2(50) NOT NULL,
    POSTAL_CODE             VARCHAR2(20),
    SWIFT_BIC               VARCHAR2(11) DEFAULT 'OCIBUS33XXX',
    CREATED_TIMESTAMP       TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL
);

-- ----------------------------------------------------------------------------
-- 2. DIM_CUSTOMER: Conformed Customer Dimension (SCD Type 2 + Masked PII)
-- ----------------------------------------------------------------------------
CREATE TABLE DIM_CUSTOMER (
    CUSTOMER_SK             NUMBER(12) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    CUSTOMER_ID             NUMBER(10) NOT NULL,
    FULL_NAME               VARCHAR2(120) NOT NULL,
    MASKED_TAX_ID           VARCHAR2(25) NOT NULL,      -- Masked: '***-**-6789' or 'XXXX-XXXX-1234'
    EMAIL                   VARCHAR2(100),              -- Cleansed, lowercase valid email or NULL
    PHONE_STANDARDIZED      VARCHAR2(30),               -- Standardized E.164 or formatted string
    STATUS                  VARCHAR2(20) NOT NULL,      -- 'ACTIVE', 'INACTIVE', 'SUSPENDED', 'DECEASED'
    KYC_STATUS              VARCHAR2(20) NOT NULL,      -- 'VERIFIED', 'PENDING'
    CREDIT_SCORE            NUMBER(4),
    DATE_OF_BIRTH           DATE,                       -- Converted from YYYYMMDD
    CITY                    VARCHAR2(50),
    STATE_PROV              VARCHAR2(50),
    START_DATE              DATE NOT NULL,              -- SCD Type 2 Valid From
    END_DATE                DATE,                       -- SCD Type 2 Valid To (NULL if current)
    IS_CURRENT              VARCHAR2(1) DEFAULT 'Y' NOT NULL, -- 'Y' or 'N'
    DW_INSERT_DATE          TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT CHK_CUST_STATUS CHECK (STATUS IN ('ACTIVE', 'INACTIVE', 'SUSPENDED', 'DECEASED')),
    CONSTRAINT CHK_CUST_KYC CHECK (KYC_STATUS IN ('VERIFIED', 'PENDING')),
    CONSTRAINT CHK_CUST_CURRENT CHECK (IS_CURRENT IN ('Y', 'N'))
);

-- ----------------------------------------------------------------------------
-- 3. DIM_ACCOUNT: Standardized Account Master
-- ----------------------------------------------------------------------------
CREATE TABLE DIM_ACCOUNT (
    ACCOUNT_SK              NUMBER(12) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ACCOUNT_NUMBER          VARCHAR2(20) NOT NULL UNIQUE,
    CUSTOMER_SK             NUMBER(12) NOT NULL,
    BRANCH_SK               NUMBER(10) NOT NULL,
    ACCOUNT_TYPE            VARCHAR2(30) NOT NULL,      -- 'SAVINGS', 'CHECKING', 'MONEY_MARKET', 'LOAN', 'CERTIFICATE_OF_DEPOSIT'
    CURRENCY_CODE           VARCHAR2(3) DEFAULT 'USD' NOT NULL,
    CURRENT_BALANCE         NUMBER(18, 2) NOT NULL,
    INTEREST_RATE           NUMBER(5, 2) NOT NULL,
    STATUS                  VARCHAR2(20) NOT NULL,      -- 'ACTIVE', 'CLOSED', 'DORMANT'
    OPEN_DATE               DATE NOT NULL,
    OVERDRAFT_LIMIT         NUMBER(18, 2) DEFAULT 0.00 NOT NULL,
    DW_INSERT_DATE          TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT FK_ACCT_CUST FOREIGN KEY (CUSTOMER_SK) REFERENCES DIM_CUSTOMER(CUSTOMER_SK),
    CONSTRAINT FK_ACCT_BRANCH FOREIGN KEY (BRANCH_SK) REFERENCES DIM_BRANCH(BRANCH_SK),
    CONSTRAINT CHK_ACCT_STATUS CHECK (STATUS IN ('ACTIVE', 'CLOSED', 'DORMANT')),
    CONSTRAINT CHK_ACCT_TYPE CHECK (ACCOUNT_TYPE IN ('SAVINGS', 'CHECKING', 'MONEY_MARKET', 'LOAN', 'CERTIFICATE_OF_DEPOSIT'))
);

-- ----------------------------------------------------------------------------
-- 4. FACT_TRANSACTIONS: Core Financial Ledger Transactions
-- ----------------------------------------------------------------------------
CREATE TABLE FACT_TRANSACTIONS (
    TXN_SK                  NUMBER(18) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    TXN_ID                  VARCHAR2(30) NOT NULL UNIQUE,
    ACCOUNT_SK              NUMBER(12) NOT NULL,
    TXN_TIMESTAMP           TIMESTAMP WITH TIME ZONE NOT NULL,
    TXN_TYPE                VARCHAR2(10) NOT NULL,      -- 'DEBIT', 'CREDIT'
    CHANNEL                 VARCHAR2(20) NOT NULL,      -- 'ATM', 'ONLINE_BANKING', 'UPI', 'POS', 'BRANCH'
    AMOUNT                  NUMBER(18, 2) NOT NULL,
    BALANCE_AFTER_TXN       NUMBER(18, 2) NOT NULL,
    AML_FLAG                VARCHAR2(1) DEFAULT 'N' NOT NULL, -- 'Y' if transaction amount > 10,000 threshold
    TXN_STATUS              VARCHAR2(20) DEFAULT 'SUCCESS' NOT NULL,
    DW_INSERT_DATE          TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT FK_TXN_ACCT FOREIGN KEY (ACCOUNT_SK) REFERENCES DIM_ACCOUNT(ACCOUNT_SK),
    CONSTRAINT CHK_TXN_TYPE CHECK (TXN_TYPE IN ('DEBIT', 'CREDIT')),
    CONSTRAINT CHK_TXN_AML CHECK (AML_FLAG IN ('Y', 'N'))
);

-- ----------------------------------------------------------------------------
-- 5. FACT_LOAN_PORTFOLIO: Core Credit and Loan Details
-- ----------------------------------------------------------------------------
CREATE TABLE FACT_LOAN_PORTFOLIO (
    LOAN_SK                 NUMBER(12) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    LOAN_ID                 VARCHAR2(20) NOT NULL UNIQUE,
    ACCOUNT_SK              NUMBER(12) NOT NULL,
    CUSTOMER_SK             NUMBER(12) NOT NULL,
    LOAN_PRODUCT            VARCHAR2(50) NOT NULL,
    PRINCIPAL_AMOUNT        NUMBER(18, 2) NOT NULL,
    OUTSTANDING_BALANCE     NUMBER(18, 2) NOT NULL,
    INTEREST_RATE           NUMBER(5, 2) NOT NULL,
    MONTHLY_EMI             NUMBER(18, 2) NOT NULL,
    TENURE_MONTHS           NUMBER(5) NOT NULL,
    DISBURSEMENT_DATE       DATE NOT NULL,
    DELINQUENCY_STATUS      VARCHAR2(30) NOT NULL,      -- 'PERFORMING', 'WATCHLIST_30_DPD', 'SUBSTANDARD_60_DPD', 'NPA_90_PLUS_DPD'
    DW_INSERT_DATE          TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT FK_LOAN_ACCT FOREIGN KEY (ACCOUNT_SK) REFERENCES DIM_ACCOUNT(ACCOUNT_SK),
    CONSTRAINT FK_LOAN_CUST FOREIGN KEY (CUSTOMER_SK) REFERENCES DIM_CUSTOMER(CUSTOMER_SK)
);

-- ----------------------------------------------------------------------------
-- 6. DAILY_BALANCE_SUMMARY: Reconciliation & Financial Balance Rollup Mart
-- ----------------------------------------------------------------------------
CREATE TABLE DAILY_BALANCE_SUMMARY (
    SUMMARY_SK              NUMBER(12) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    SNAPSHOT_DATE           DATE NOT NULL,
    ACCOUNT_SK              NUMBER(12) NOT NULL,
    OPENING_BALANCE         NUMBER(18, 2) NOT NULL,
    TOTAL_DEBIT_AMOUNT      NUMBER(18, 2) DEFAULT 0.00 NOT NULL,
    TOTAL_CREDIT_AMOUNT     NUMBER(18, 2) DEFAULT 0.00 NOT NULL,
    CLOSING_BALANCE         NUMBER(18, 2) NOT NULL,
    TOTAL_TXN_COUNT         NUMBER(10) DEFAULT 0 NOT NULL,
    RECONCILIATION_STATUS   VARCHAR2(20) DEFAULT 'BALANCED' NOT NULL,
    DW_INSERT_DATE          TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT FK_BAL_ACCT FOREIGN KEY (ACCOUNT_SK) REFERENCES DIM_ACCOUNT(ACCOUNT_SK),
    CONSTRAINT CHK_RECON_STATUS CHECK (RECONCILIATION_STATUS IN ('BALANCED', 'DISCREPANCY'))
);

-- ----------------------------------------------------------------------------
-- 7. ETL_REJECTED_RECORDS: Error Quarantine / Discard Table for ETL Testing
-- ----------------------------------------------------------------------------
CREATE TABLE ETL_REJECTED_RECORDS (
    REJECT_ID               NUMBER(12) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    SOURCE_TABLE            VARCHAR2(50) NOT NULL,
    SOURCE_RECORD_KEY       VARCHAR2(50) NOT NULL,
    REJECT_REASON           VARCHAR2(255) NOT NULL,
    RAW_RECORD_PAYLOAD      VARCHAR2(1000) NOT NULL,
    QUARANTINE_TIMESTAMP    TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL
);

-- Performance and Query Optimization Indexes
CREATE INDEX IDX_ORA_CUST_NATURAL ON DIM_CUSTOMER(CUSTOMER_ID);
-- ACCOUNT_NUMBER is automatically indexed by the UNIQUE constraint in DIM_ACCOUNT
CREATE INDEX IDX_ORA_TXN_ACCT_DATE ON FACT_TRANSACTIONS(ACCOUNT_SK, TXN_TIMESTAMP);
CREATE INDEX IDX_ORA_LOAN_ACCT ON FACT_LOAN_PORTFOLIO(ACCOUNT_SK);
CREATE INDEX IDX_ORA_REJECT_SRC ON ETL_REJECTED_RECORDS(SOURCE_TABLE);


